function getKeyAssignment%% asks for key assignment%% 2008 by Martin Rolfsglobal keys% unify key names (as this will be running on Linux and OS X) is included% in PsychDefaultSetup(2), initiated in prepScreen.m.% Target keys for responsekeys.respButtons = KbName({'UpArrow', 'DownArrow'});keys.resUp      = keys.respButtons(1);keys.resDown    = keys.respButtons(2);FlushEvents('keyDown');